def main():
    # Check if we're in the talk-master repo
    if not os.path.exists("app.py"):
        print("Error: Please run this script from the talk-master repo directory.")
        print("Clone it first: git clone https://github.com/m4hruthik/talk-master.git")
        print("Then: cd talk-master && python deploy_talkmaster.py")
        sys.exit(1)

    print("Writing files...")
    for filepath, b64_content in FILES.items():
        # Decode and write
        content = base64.b64decode(b64_content)
        os.makedirs(os.path.dirname(filepath), exist_ok=True) if os.path.dirname(filepath) else None
        with open(filepath, "wb") as f:
            f.write(content)
        print(f"  Wrote {filepath} ({len(content)} bytes)")

    print("\nStaging files...")
    for filepath in FILES:
        subprocess.run(["git", "add", filepath], check=True)

    print("Committing...")
    result = subprocess.run(
        ["git", "commit", "-m", "Premium upgrade: CSS, JavaScript, and Flask app with 30-day curriculum, audio, and progress tracking"],
        capture_output=True, text=True
    )
    if result.returncode != 0:
        print(f"Commit result: {result.stdout}")
        print(f"Errors: {result.stderr}")
    else:
        print(f"Committed: {result.stdout.strip()}")

    print("\nPushing to GitHub...")
    result = subprocess.run(["git", "push"], capture_output=True, text=True)
    if result.returncode != 0:
        print(f"Push result: {result.stdout}")
        print(f"Errors: {result.stderr}")
        print("\nIf push failed, you may need to authenticate with GitHub.")
        print("Try: gh auth login  OR  set up SSH keys  OR  use a Personal Access Token")
    else:
        print("Successfully pushed to GitHub!")
        print("\nYour TalkMaster Premium app is now live!")
        print("Run: python app.py  to start the server at http://localhost:5000")

if __name__ == "__main__":
    main()
